mapper.select:


    deleted = 0
     and title like concat('%', #{title}, '%')
     and content like concat('%', #{content}, '%')
     and type = #{type}
     and publisher like concat('%', #{publisher}, '%')

         and status = #{status}

            and status = 2

            and (publish_time is null or publish_time <= sysdate())

         and status != 3


        and (target_type = 'all' or (target_type = 'class' and target_id = #{visibleClazzId}))

     and target_type = #{targetType}
     and target_id = #{targetId}
     and publish_time = #{publishTime}

order by id desc
